{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 청년 기본 조례상 청년 주거 지원에 보증보험료와 이삿짐 비용이 포함되는지",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 청년 기본 조례 제13조제3항에 따르면, 시장은 청년의 안정적 생활을 보장하기 위하여 예산의 범위에서 주거와 관련한 보증보험 비용 등을 지원할 수 있고, 청년 스스로 자립할 수 있도록 독립가구를 형성하기 위하여 이사에 소요되는 비용을 이용권 등으로 지급할 수 있습니다. 따라서 보증보험료와 이삿짐 비용은 청년 주거 지원의 대상에 포함될 수 있습니다. 다만 지원은 예산의 범위에서 이루어지며, 보증보험 비용은 ‘지원할 수 있다’는 재량 규정이고 이사 비용은 ‘이용권 등으로 지급할 수 있다’는 방식으로 규정되어 있습니다.",
          "b_ids": "청년:제13조제3항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
